package solution

import (
	"strings"
)

// Normalize is exported: the package's public API.
func Normalize(s string) string {
	return clean(s)
}

// clean is unexported: an internal helper, hidden from callers.
func clean(s string) string {
	return strings.ToLower(strings.TrimSpace(s))
}

codeLab.testHarness:
package solution

import "testing"

func TestNormalize(t *testing.T) {
	cases := []struct {
		in, want string
	}{
		{"  Hello ", "hello"},
		{"GoLang", "golang"},
		{"", ""},
	}
	for _, c := range cases {
		if got := Normalize(c.in); got != c.want {
			t.Errorf("Normalize(%q)=%q want %q", c.in, got, c.want)
		}
	}
}

