package validate

import "strings"

// IsEmail is the exported public API.
func IsEmail(s string) bool {
	return hasSingleAt(s)
}

// hasSingleAt is an unexported helper (implementation detail).
func hasSingleAt(s string) bool {
	i := strings.Index(s, "@")
	if i <= 0 || i == len(s)-1 {        // need text before and after @
		return false
	}
	return strings.Count(s, "@") == 1   // exactly one @
}
